'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],icon=id=>`<svg class="icon"><use href="#${id}"/></svg>`,clone=x=>JSON.parse(JSON.stringify(x)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='robotlab-teaching-v3';
const initial={vision:{name:'工业零件图像分割与轮廓检测',course:'机器视觉基础',minutes:30,pass:60,description:'独立完成图像二值化与轮廓筛选，检出图像中的 4 个零件，并说明参数选择依据。',method:'fixed',editable:true,tmin:85,tmax:150,amin:200,amax:1800,agent:{concept:true,diagnose:false,recommend:false,code:false,limit:3},rubric:[{id:'threshold',name:'二值化阈值选择',detail:'阈值处于教师设置的合理区间',weight:30,on:true},{id:'area',name:'轮廓面积筛选',detail:'最小轮廓面积处于允许范围',weight:25,on:true},{id:'count',name:'有效目标检出',detail:'按正确检出目标数占 4 个参考目标的比例计分',weight:30,on:true},{id:'analysis',name:'实验结果解释',detail:'教师根据参数选择依据与现象分析人工评阅',weight:15,on:true}]},robot:{name:'已知位姿下的零件抓取与分类',course:'机械臂操作实训',minutes:40,pass:60,description:'根据给定零件位姿完成抓取，将圆形与方形零件放入指定料框，并说明操作策略。',pieces:4,mapping:{circle:'A',square:'B'},safeHeight:60,speedCap:60,agent:{concept:true,diagnose:false,recommend:false,code:false,limit:3},rubric:[{id:'pick',name:'抓取任务完成',detail:'按成功抓取数量占任务零件数的比例计分',weight:40,on:true},{id:'sort',name:'分类放置正确',detail:'按放入指定料框的数量占任务零件数的比例计分',weight:30,on:true},{id:'safe',name:'运动参数规范',detail:'接近高度与运动速度均符合任务要求',weight:20,on:true},{id:'analysis',name:'操作策略说明',detail:'教师根据操作说明与运行证据人工评阅',weight:10,on:true}]} };
let db=loadCatalog(initial);
let state={role:'teacher',domain:'vision',page:'courses',caseId:'case-cv-101',courseId:'cv-basic',mode:'exam',recordMode:'exam',tab:'task',threshold:128,minArea:400,contours:true,selected:0,sorted:[],running:false,phase:0,activeObject:0,grip:false,offset:0,view:'linked'};
let objects=[];const allObjects=[{id:'01',shape:'circle',x:168,y:135,r:27,v:183,wx:28,wy:-45},{id:'02',shape:'square',x:350,y:120,r:26,v:166,wx:100,wy:7},{id:'03',shape:'circle',x:265,y:290,r:23,v:197,wx:-30,wy:46},{id:'04',shape:'square',x:465,y:280,r:25,v:155,wx:65,wy:85}];
let animFrame=0,runStart=0,runQueue=[],runSnapshot=null,toastTimer,clockTimer;
function save(){try{localStorage.setItem(STORE,JSON.stringify(db))}catch{toast('浏览器存储不可用，本次修改仅在当前页面保留')}}
const cfg=()=>selectedCase().draft,pub=()=>selectedCase().published||{...selectedCase().draft,version:0},attempt=()=>db.attempts[attemptKey()];
function dirty(){const entry=selectedCase();if(!entry.published)return true;const a=clone(entry.published);delete a.version;delete a.publishedAt;return JSON.stringify(a)!==JSON.stringify(entry.draft)}
function active(){return attempt()?.status==='active'}function currentConfig(){return attempt()?.config||pub()}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function remaining(a){return Math.max(0,Math.ceil((a.config.minutes*60000-(Date.now()-a.started))/1000))}function timeFormat(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function detected(o){return state.threshold>=48&&state.threshold<o.v&&(o.shape==='circle'?Math.PI*o.r*o.r:4*o.r*o.r)>=state.minArea}function count(){return objects.filter(detected).length}
function destination(o){return state.role==='student'?(attempt()?.lastRun?.mapping||attempt()?.params.mapping||pub().mapping||initial.robot.mapping)[o.shape]:(cfg().mapping||initial.robot.mapping)[o.shape]}
function syncDrawing(){const c=state.role==='teacher'?cfg():currentConfig();const a=state.role==='student'?attempt():null;objects=clone(allObjects).slice(0,state.domain==='robot'?Number(c.pieces):4);state.selected=Math.min(state.selected,objects.length-1);state.threshold=a?.params.threshold??(c.method==='otsu'?118:128);state.minArea=a?.params.area??400;state.offset=a?.params.offset??0;if(!state.running){state.sorted=state.domain==='robot'?(a?.lastRun?.items||[]).filter(x=>x.picked).map(x=>x.index):[];state.grip=a?.params.grip||false}}
function header(){return `<header class="top"><div class="brand"><span class="mark">${icon('cube')}</span><div>具身工坊<small>ROBOT LEARNING STUDIO</small></div></div><nav class="topnav"><button data-page="config" class="${state.page==='config'?'active':''}">${state.role==='teacher'?'案例配置':'考核工作台'}</button><button data-page="records" class="${state.page==='records'?'active':''}">${state.role==='teacher'?'考核评阅':'我的考核记录'}</button></nav><div class="spacer"></div><span class="nav-status">${state.role==='teacher'?'教学设计工作区':'独立案例考核'}</span><div class="role-switch" aria-label="原型角色切换"><button data-role="teacher" class="${state.role==='teacher'?'active':''}">教师配置</button><button data-role="student" class="${state.role==='student'?'active':''}">学生考核</button></div><div class="avatar">${state.role==='teacher'?'师':'林'}</div></header>`}
function rail(){return `<aside class="rail"><button data-page="config" class="${state.page==='config'?'active':''}">${icon('book')}${state.role==='teacher'?'案例配置':'考核台'}</button><button data-domain="vision" class="${state.domain==='vision'&&state.page==='config'?'active':''}">${icon('vision')}机器视觉</button><button data-domain="robot" class="${state.domain==='robot'&&state.page==='config'?'active':''}">${icon('robot')}机械操控</button><button data-page="records" class="${state.page==='records'?'active':''}">${icon('chart')}${state.role==='teacher'?'评阅':'记录'}</button><button class="bottom" id="aboutBtn">${icon('settings')}说明</button></aside>`}
function domains(){return `<div class="domain-cards">${['vision','robot'].map(k=>`<button class="domain-card ${k==='robot'?'robot':''} ${attemptKey()===k?'active':''}" data-domain="${k}"><span class="domain-icon">${icon(k==='vision'?'vision':'robot')}</span><div><h3>${k==='vision'?'机器视觉教学':'机械臂操控教学'}</h3><p>${k==='vision'?'图像处理 · 阈值调优 · 轮廓检测':'已知位姿 · 抓取操作 · 分类放置'}</p></div><span class="tag">独立案例 ${k==='vision'?'CV-01':'RM-01'}</span></button>`).join('')}</div>`}
function render(){syncDrawing();const teacher=state.role==='teacher';$('#app').innerHTML=header()+`<div class="shell">${rail()}<main class="main"><div class="page-wrap"><div class="breadcrumb">${teacher?'教师工作区':'学生工作区'} <span>/</span> ${state.page==='records'?'考核记录':state.domain==='vision'?'机器视觉':'机械臂操控'} <span>/</span> ${state.page==='records'?(teacher?'考核评阅':'我的记录'):(teacher?'案例配置':'独立考核')}</div>${state.page==='records'?recordsPage():teacher?teacherPage():studentPage()}<footer class="footer"><span>● ${teacher?'教师配置':'学生考核'} · 原型角色切换</span><span>浏览器本地保存</span><div class="spacer"></div><span>交互原型 · 合成图像与运动演示 · Agent 为预设引导</span><span>具身工坊 / 教学实验环境</span></footer></div></main></div>`;bindGlobal();if(state.page==='config'){teacher?bindTeacher():bindStudent();requestAnimationFrame(()=>{drawCameras();drawScene();drawHistogram()})}else bindRecords();updateClock()}
function teacherPage(){const c=cfg(),tabs=[['base','案例信息'],['task',state.domain==='vision'?'视觉参数考点':'抓取分类任务'],['score','评分规则'],['agent','Agent 提示权限']];return `<div class="titleline"><h1>案例配置</h1><span class="tag">教师端</span><div class="titleactions"><span class="saved-indicator" id="saveIndicator">${dirty()?'草稿有修改':'已与发布版本同步'}</span><button class="btn" id="saveDraft">${icon('save')}保存草稿</button><button class="btn primary" id="publishBtn">发布考核配置</button></div></div><p class="subtitle">分别设计视觉与操控课程，为每个独立案例设置考点、评分标准和助教边界。</p>${domains()}<div class="teacher-layout"><aside class="config-sidebar"><section class="panel"><div class="panelhead">配置导航 <small>${esc(selectedCase().templateId)}</small></div><div class="config-menu">${tabs.map(([id,title],i)=>`<button class="${state.tab===id?'active':''}" data-tab="${id}"><span class="num">${i+1}</span>${title}</button>`).join('')}</div><div class="sidebar-note"><strong>按教学类型独立组织</strong>${state.domain==='vision'?'本案例只包含图像处理与视觉考点，不包含机械臂任务。':'本案例采用已知零件位姿，不包含相机、二值化与识别流程。'}</div></section><section class="panel"><div class="panelhead">发布状态 <span class="tag green">v${pub().version}</span></div><div class="summary-list"><div><span>学生可见版本</span><strong>已发布 v${pub().version}</strong></div><div><span>考核时长</span><strong>${pub().minutes} 分钟</strong></div><div><span>合格标准</span><strong>${pub().pass} / 100 分</strong></div></div><button class="mini-link" id="previewStudent">进入学生考核 ↗</button></section></aside><section class="panel"><div class="editor-title"><h2>${tabs.find(x=>x[0]===state.tab)[1]}</h2><p>${{base:'设置案例背景和考核安排。每个案例拥有独立的发布版本。',task:state.domain==='vision'?'选择需要考察的视觉能力，设置参数操作范围与评分依据。':'配置已知位姿零件、目标料框及机械臂操作要求。',score:'分配各考点的分值，自动评测与教师评阅共同组成总成绩。',agent:'逐项控制考核期间允许提供的帮助，学生端将按发布权限执行。'}[state.tab]}</p></div><div class="editor-body"><div id="validationArea"></div>${{base:baseEditor,task:taskEditor,score:scoreEditor,agent:agentEditor}[state.tab]()}</div><div class="editor-footer"><span id="editorStatus">修改自动暂存至本机草稿</span><button class="btn ${state.tab==='agent'?'primary':''}" id="nextConfig">${state.tab==='agent'?'检查并发布':'下一项配置 →'}</button></div></section><aside class="teacher-preview">${previewPanel(c)}${policyPanel(c.agent)}<section class="panel preview-card"><div class="panelhead">配置检查 <small>发布前校验</small></div><div class="summary-list" id="configChecklist"></div></section></aside></div>`}
function baseEditor(){const c=cfg();return `<div class="form-item"><label for="caseName">案例名称</label><input id="caseName" data-field="name" maxlength="60" value="${esc(c.name)}"></div><div class="form-grid"><div class="form-item"><label for="courseName">所属课程</label><select id="courseName" data-course-relation>${db.courses.filter(x=>x.domain===state.domain).map(x=>`<option value="${x.id}" ${x.id===c.courseId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="form-item"><label>教学类型</label><input disabled value="${state.domain==='vision'?'机器视觉 · 独立案例':'机械臂操控 · 独立案例'}"></div><div class="form-item"><label for="examMinutes">考核时长 / 分钟</label><input id="examMinutes" data-field="minutes" type="number" min="5" max="180" value="${c.minutes}"></div><div class="form-item"><label for="passScore">合格分数 / 分</label><input id="passScore" data-field="pass" type="number" min="0" max="100" value="${c.pass}"></div></div><div class="form-divider"></div><div class="form-item"><label for="description">学生任务说明</label><textarea id="description" data-field="description" maxlength="1200">${esc(c.description)}</textarea><small>考核开始前展示给学生。请明确目标与提交要求。</small></div><div class="subtle-note blue">发布后，新考核采用新版本；正在进行的考核保留开始时的配置与评分标准。</div>`}
function checkPoint(id,title,desc){const row=cfg().rubric.find(x=>x.id===id);return `<label class="checkline"><input type="checkbox" data-point="${id}" ${row.on?'checked':''}><div><strong>${title}</strong><small>${desc}</small></div><span class="tag">${row.weight} 分</span></label>`}
function taskEditor(){const c=cfg();if(state.domain==='vision')return `<div class="fieldtitle">视觉能力考点 <span>与机械臂操控分开考核</span></div>${checkPoint('threshold','二值化阈值选择','学生调整阈值，观察前景分离和零件完整性。')}${checkPoint('area','轮廓面积筛选','学生使用最小面积过滤轮廓，保留有效目标。')}${checkPoint('count','有效目标检出','固定合成样本包含 4 个独立零件，按正确检出比例计分。')}<div class="form-divider"></div><div class="form-grid"><div class="form-item"><label for="caseMethod">指定二值化方法</label><select id="caseMethod" data-field="method"><option value="fixed" ${c.method==='fixed'?'selected':''}>固定阈值二值化</option><option value="otsu" ${c.method==='otsu'?'selected':''}>Otsu 自动阈值（样本演示）</option></select></div><div class="form-item"><label>学生阈值操作权限</label><select data-field="editable" aria-label="学生阈值操作权限"><option value="true" ${c.editable?'selected':''}>允许调整阈值</option><option value="false" ${!c.editable?'selected':''}>锁定初始阈值</option></select></div><div class="form-item"><label for="tmin">合理阈值下限 / 0–255</label><input id="tmin" type="number" min="0" max="255" data-field="tmin" value="${c.tmin}"></div><div class="form-item"><label for="tmax">合理阈值上限 / 0–255</label><input id="tmax" type="number" min="0" max="255" data-field="tmax" value="${c.tmax}"></div><div class="form-item"><label for="amin">合理最小面积下限 / px²</label><input id="amin" type="number" min="0" max="6000" data-field="amin" value="${c.amin}"></div><div class="form-item"><label for="amax">合理最小面积上限 / px²</label><input id="amax" type="number" min="0" max="6000" data-field="amax" value="${c.amax}"></div></div><div class="subtle-note">合理区间作为教师评分依据，不直接显示在学生考题中。样本包含 4 个零件；此处不涉及抓取、运动规划或分拣执行。</div>`;
return `<div class="fieldtitle">抓取分类任务 <span>给定位姿，无视觉前置任务</span></div><div class="form-grid"><div class="form-item"><label for="pieces">待操作零件数量</label><select id="pieces" data-field="pieces"><option value="4" ${c.pieces===4?'selected':''}>4 个零件 · 圆形与方形各 2 个</option><option value="2" ${c.pieces===2?'selected':''}>2 个零件 · 圆形与方形各 1 个</option></select></div><div class="form-item"><label>位姿来源</label><input value="案例给定坐标表" disabled></div></div><div class="form-divider"></div><div class="fieldtitle">分类目标规则 <span>各类别可配置不同料框</span></div><div class="form-grid"><div class="form-item"><label for="circleBin">圆形零件放置至</label><select id="circleBin" data-mapping="circle">${binOptions(c.mapping.circle)}</select></div><div class="form-item"><label for="squareBin">方形零件放置至</label><select id="squareBin" data-mapping="square">${binOptions(c.mapping.square)}</select></div><div class="form-item"><label for="safeHeight">最低接近高度 / mm</label><input id="safeHeight" data-field="safeHeight" type="number" min="20" max="150" value="${c.safeHeight}"></div><div class="form-item"><label for="speedCap">允许最高速度 / %</label><select id="speedCap" data-field="speedCap">${[30,60,100].map(n=>`<option value="${n}" ${c.speedCap===n?'selected':''}>${n}%</option>`).join('')}</select></div></div><div class="form-divider"></div><div class="fieldtitle">考核项目 <span>可在评分规则中调整分值</span></div>${checkPoint('pick','抓取任务完成','根据运行记录统计成功抓取的零件数量。')}${checkPoint('sort','分类放置正确','对照教师设定规则检查目标料框。')}${checkPoint('safe','运动参数规范','检查接近高度和速度是否均符合要求。')}<div class="subtle-note">机械臂考核直接使用案例给定的坐标与类别。学生在独立的操控工作台设置抓取参数和放置规则，无需完成机器视觉实验。</div>`}
function binOptions(v){return ['A','B'].map(b=>`<option value="${b}" ${v===b?'selected':''}>料框 ${b}</option>`).join('')}
function total(c=cfg()){return c.rubric.filter(r=>r.on).reduce((s,r)=>s+Number(r.weight||0),0)}
function scoreEditor(){const c=cfg();return `<div class="total-bar ${total()!==100?'invalid':''}" id="totalBar"><span>启用考点总分 <small> · 需合计 100 分</small></span><span><b id="totalScore">${total()}</b> / 100</span></div><div class="table-scroll"><table class="rubric"><thead><tr><th style="width:37%">考核项目</th><th style="width:37%">计分依据</th><th>分值</th><th>启用</th></tr></thead><tbody>${c.rubric.map(r=>`<tr><td>${r.name}<small>${r.id==='analysis'?'教师人工评阅':'自动评测'}</small></td><td>${r.detail}</td><td class="weight-cell"><input class="rule-input weight" type="number" min="0" max="100" data-weight="${r.id}" aria-label="${r.name}分值" value="${r.weight}"> 分</td><td><input type="checkbox" data-score-point="${r.id}" aria-label="启用${r.name}" ${r.on?'checked':''} style="accent-color:var(--blue)"></td></tr>`).join('')}</tbody></table></div><div class="form-divider"></div><div class="form-grid"><div class="form-item"><label>合格分数 / 分</label><input data-field="pass" aria-label="合格分数" type="number" min="0" max="100" value="${c.pass}"></div><div class="form-item"><label>成绩构成</label><input disabled value="自动评测 + 教师评阅"></div></div><div class="subtle-note blue">学生交卷时冻结参数、运行证据与考核版本。人工评阅项未完成前，成绩标为「待教师评阅」，不提前判定合格。</div>`}
const permissionInfo=[['concept','概念解释','允许解释术语、单位与界面操作，不提供当前案例答案。'],['diagnose','当前结果诊断','允许读取本次参数与结果，指出需要检查的环节。'],['recommend','参数与策略建议','允许给出具体参数建议或分类策略建议。'],['code','示例程序提示','允许提供当前教学类型的示例伪代码。']];
function agentEditor(){const a=cfg().agent;return `<div class="fieldtitle">考核期间允许的帮助 <span>学生端按发布权限执行</span></div><div class="policy-presets"><button data-preset="strict">严格考核</button><button data-preset="guided">有限引导</button><button data-preset="practice">开放练习</button></div>${permissionInfo.map(([id,name,desc])=>`<div class="permission-row"><div><h4>${name}</h4><p>${desc}</p></div><button class="switch ${a[id]?'on':''}" data-permission="${id}" role="switch" aria-checked="${a[id]}" aria-label="${name}"></button></div>`).join('')}<div class="form-divider"></div><div class="form-grid"><div class="form-item"><label for="hintLimit">每次考核最多提示次数</label><input id="hintLimit" data-agent-limit type="number" min="0" max="20" value="${a.limit}"><small>一次有效帮助计 1 次。拒绝的请求不消耗次数。</small></div><div class="form-item"><label>使用记录</label><input disabled value="记录提示类型、时间与次数"></div></div><div class="subtle-note">关闭的帮助类型在学生端禁用。自由提问仅接收术语与操作说明类问题，并受「概念解释」权限限制；当前原型不连接外部模型。</div>`}
function previewPanel(c){return `<section class="panel preview-card"><div class="panelhead">学生案例预览 <span class="type-label ${state.domain==='robot'?'robot':''}">${state.domain==='vision'?'机器视觉':'机械操控'}</span></div><div class="preview-screen ${state.domain==='robot'?'robot-preview':''}"><canvas id="${state.domain==='vision'?'original':'scene'}" aria-label="${state.domain==='vision'?'视觉案例样本预览':'机械臂案例场景预览'}"></canvas><div class="preview-caption">${state.domain==='vision'?'固定图像样本 · 4 个参考目标':'给定零件位姿 · 独立抓取任务'}</div></div><div class="summary-list"><div><span>案例名称</span><strong id="previewName">${esc(c.name)}</strong></div><div><span>时长 / 合格分</span><strong id="previewTime">${c.minutes} 分钟 / ${c.pass} 分</strong></div><div><span>启用考点</span><strong id="previewPoints">${c.rubric.filter(x=>x.on).length} 项</strong></div><div><span>评分方式</span><strong>自动评测 + 人工评阅</strong></div></div></section>`}
function policyPanel(a){return `<section class="panel preview-card"><div class="panelhead"><span class="agenttitle">${icon('spark')} Agent 权限摘要</span></div><div class="policy-list" id="policySummary">${permissionSummary(a)}</div></section>`}
function permissionSummary(a){return permissionInfo.map(([id,name])=>`<div><span>${name}</span><span class="${a[id]?'yes':'no'}">${a[id]?'允许':'禁用'}</span></div>`).join('')+`<div><span>提示次数上限</span><span>${a.limit} 次 / 考核</span></div>`}
function validate(c=cfg(),k=state.domain){const errors=[];if(!c.name.trim())errors.push('请填写案例名称。');if(!c.description.trim())errors.push('请填写学生任务说明。');if(!Number.isInteger(c.minutes)||c.minutes<5||c.minutes>180)errors.push('考核时长需为 5–180 的整数。');if(!Number.isFinite(c.pass)||c.pass<0||c.pass>100)errors.push('合格分数需为 0–100。');if(total(c)!==100)errors.push(`启用考点总分为 ${total(c)} 分，请调整至 100 分。`);if(c.rubric.some(x=>!Number.isInteger(x.weight)||x.weight<0||x.weight>100))errors.push('各考点分值需为 0–100 的整数。');if(!c.rubric.some(x=>x.on&&x.id!=='analysis'))errors.push('至少启用一项自动评测考点。');if(!Number.isInteger(c.agent.limit)||c.agent.limit<0||c.agent.limit>20)errors.push('提示次数需为 0–20 的整数。');if(k==='vision'){if([c.tmin,c.tmax].some(n=>!Number.isInteger(n)||n<0||n>255)||c.tmin>c.tmax)errors.push('阈值区间需为 0–255 的整数，且下限不大于上限。');if([c.amin,c.amax].some(n=>!Number.isInteger(n)||n<0||n>6000)||c.amin>c.amax)errors.push('面积区间需为 0–6000 的整数，且下限不大于上限。');if(c.method==='otsu'&&c.rubric.find(r=>r.id==='threshold').on)errors.push('考察阈值选择时，请选择固定阈值二值化；Otsu 将自动确定阈值。');if(!c.editable&&c.method==='fixed'&&c.rubric.find(r=>r.id==='threshold').on)errors.push('启用阈值选择考点时，需要允许学生调整阈值。')}else{if(!Number.isInteger(c.safeHeight)||c.safeHeight<20||c.safeHeight>150)errors.push('最低接近高度需为 20–150 mm 的整数。')}return errors}
function draftChanged(){save();$('#saveIndicator').textContent=dirty()?'草稿有修改':'已与发布版本同步';$('#editorStatus').textContent='草稿已暂存 · 发布后对新考核生效';$('#previewName').textContent=cfg().name;$('#previewTime').textContent=`${cfg().minutes} 分钟 / ${cfg().pass} 分`;$('#previewPoints').textContent=`${cfg().rubric.filter(x=>x.on).length} 项`;$('#policySummary').innerHTML=permissionSummary(cfg().agent);if($('#totalScore')){$('#totalScore').textContent=total();$('#totalBar').classList.toggle('invalid',total()!==100)}checklist();$('#validationArea').innerHTML=''}
function checklist(){const errors=validate();$('#configChecklist').innerHTML=`<div><span>教学任务独立</span><strong class="done-label">已分开</strong></div><div><span>总分 100 分</span><strong style="color:${total()===100?'#299a7a':'#bd8950'}">${total()} / 100</strong></div><div><span>发布校验</span><strong style="color:${errors.length?'#bd8950':'#299a7a'}">${errors.length?errors.length+' 项待修正':'可以发布'}</strong></div>`}
function publish(){const errors=validate();if(errors.length){$('#validationArea').innerHTML=`<div class="validation" role="alert">${errors.map(esc).join('<br>')}</div>`;toast('配置未发布，请先修正校验项');return}const k=state.domain;selectedCase().published={...clone(cfg()),version:pub().version+1,publishedAt:Date.now()};selectedCase().courseId=cfg().courseId;selectedCase().updated=Date.now();save();render();toast(`已发布${k==='vision'?'机器视觉':'机械臂操控'}考核 v${pub().version}，其他案例保持独立`)}
function bindTeacher(){$$('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render()});$$('[data-field]').forEach(el=>{const ev=el.tagName==='SELECT'?'change':'input';el.addEventListener(ev,()=>{const key=el.dataset.field;cfg()[key]=el.type==='number'?Number(el.value):['minutes','pieces','speedCap'].includes(key)?Number(el.value):key==='editable'?el.value==='true':el.value;draftChanged();if(key==='pieces'){syncDrawing();drawScene()}})});$$('[data-mapping]').forEach(el=>el.onchange=()=>{cfg().mapping[el.dataset.mapping]=el.value;draftChanged();drawScene()});$$('[data-point],[data-score-point]').forEach(el=>el.onchange=()=>{cfg().rubric.find(r=>r.id===(el.dataset.point||el.dataset.scorePoint)).on=el.checked;draftChanged()});$$('[data-weight]').forEach(el=>el.oninput=()=>{cfg().rubric.find(r=>r.id===el.dataset.weight).weight=Number(el.value);draftChanged()});$$('[data-permission]').forEach(el=>el.onclick=()=>{const id=el.dataset.permission;cfg().agent[id]=!cfg().agent[id];el.classList.toggle('on',cfg().agent[id]);el.setAttribute('aria-checked',cfg().agent[id]);draftChanged()});if($('[data-agent-limit]'))$('[data-agent-limit]').oninput=e=>{cfg().agent.limit=Number(e.target.value);draftChanged()};$$('[data-preset]').forEach(el=>el.onclick=()=>{const p=el.dataset.preset;cfg().agent={concept:p!=='strict',diagnose:p==='practice',recommend:p==='practice',code:p==='practice',limit:p==='strict'?0:p==='guided'?3:10};save();render();toast('提示权限预设已应用至草稿')});$('#saveDraft').onclick=()=>{save();toast('当前案例草稿已保存，学生仍使用已发布版本')};$('#publishBtn').onclick=publish;$('#nextConfig').onclick=()=>{if(state.tab==='agent')publish();else{state.tab=['base','task','score','agent'][['base','task','score','agent'].indexOf(state.tab)+1];render()}};$('#previewStudent').onclick=()=>{state.role='student';state.page='config';render();toast('学生考核使用该案例已发布的配置')};checklist()}
function newAttempt(k){const c=clone(pub());if(state.mode==='practice')c.agent={concept:true,diagnose:true,recommend:true,code:true,limit:20};return {id:'EX-'+crypto.randomUUID().slice(0,8).toUpperCase(),domain:k,caseId:state.caseId,courseId:c.courseId,mode:state.mode,status:'active',config:c,started:Date.now(),params:k==='vision'?{fields:clone(c.fields||{}),threshold:c.method==='otsu'?118:128,area:400}:{fields:clone(c.fields||{}),height:80,speed:30,mapping:{circle:'A',square:'B'},offset:0,grip:false},explanation:'',hints:[],runs:[],lastRun:null,logs:[],checks:0}}
function studentPage(){const a=attempt(),c=currentConfig(),live=active(),submitted=a?.status==='submitted',ready=!a;return `<div class="titleline"><h1>${state.domain==='vision'?'机器视觉考核':'机械臂操控考核'}</h1><span class="tag">学生端</span><div class="titleactions"><span class="attempt-status">${live?'考核进行中':submitted?'已交卷 · 操作已锁定':'等待开始'}</span>${live?`<span class="exam-clock" id="examClock">${timeFormat(remaining(a))}</span><button class="btn primary" id="submitTop">提交考核</button>`:submitted?'<button class="btn" id="viewSubmission">查看交卷结果</button><button class="btn" id="newExam">再次练习</button>':'<button class="btn primary" id="startExam">开始考核</button>'}</div></div><p class="subtitle">${state.domain==='vision'?'专注图像处理与识别能力。本案例仅提交视觉参数、检测结果与分析说明。':'使用已知零件位姿完成抓取与分类。本案例仅考核机械臂操控，不包含机器视觉流程。'}</p>${domains()}<div class="exam-banner ${submitted?'warning':''}">${icon('book')}<span>${live?`当前考核已锁定配置 v${c.version}，剩余时间 <b id="bannerClock">${timeFormat(remaining(a))}</b>。交卷后参数与证据将冻结。`:submitted?'本次考核已交卷。可查看自动评测与教师评阅进度，或开始一次新的练习。':`本案例已发布 v${c.version} · 限时 ${c.minutes} 分钟 · 满分 100 分 · ${c.pass} 分合格。点击「开始考核」后开放操作。`}</span></div><div class="student-layout"><aside class="student-sidebar"><section class="panel"><div class="panelhead">考核任务 <span class="type-label ${state.domain==='robot'?'robot':''}">${esc(selectedCase().templateId)}</span></div><div class="student-heading"><div class="eyebrow">${esc(c.course)}</div><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><div class="exam-meta"><span>${c.minutes} 分钟</span><span>配置 v${c.version}</span></div></div>${c.rubric.filter(r=>r.on).map((r,i)=>`<div class="exam-task"><span class="task-num">${i+1}</span><div><h4>${r.name}</h4><p>${r.id==='analysis'?'提交说明，由教师评阅。':taskHelp(r.id,c)}</p></div><span class="task-score">${r.weight} 分</span></div>`).join('')}</section></aside><div class="student-center">${state.domain==='vision'?visionWorkspace():robotWorkspace()}<section class="panel" style="margin-top:15px"><div class="panelhead">${state.domain==='vision'?'实验分析与解释':'操作策略与说明'} <small>${c.rubric.find(r=>r.id==='analysis').on?'教师人工评阅':'可选补充说明'}</small></div><div class="evidence-box"><label for="explanation">${state.domain==='vision'?'说明参数选择依据、分割现象与检测结果':'说明接近高度、运动速度和分类放置策略'}</label><textarea id="explanation" maxlength="2000" ${!live?'disabled':''} placeholder="${state.domain==='vision'?'例如：比较不同阈值下的轮廓完整性，说明最终参数选择理由…':'例如：说明怎样保持合适接近高度，以及各类零件如何放入指定料框…'}">${esc(a?.explanation||'')}</textarea><div class="evidence-meta"><span>与本次考核参数、运行记录一起提交</span><span id="wordCount">${a?.explanation.length||0} / 2000</span></div></div></section>${studentLogs()}<div class="submission-bar"><div><strong>${submitted?'本次交卷证据已冻结':live?'完成后提交本案例考核':'准备好后开始本案例考核'}</strong><p>${state.domain==='vision'?'提交内容：视觉参数、检测快照、分析说明、提示使用记录。':'提交内容：操控参数、抓取分类记录、操作说明、提示使用记录。'}</p></div><button class="btn ${submitted?'':'primary'}" id="bottomAction">${submitted?'查看交卷结果':live?'提交考核':'开始考核'}</button></div></div><aside class="right">${state.domain==='vision'?visionParams():robotParams()}${studentAgent()}<section class="panel" style="margin-top:15px"><div class="panelhead">本次考核规则 <small>已发布 v${c.version}</small></div><div class="summary-list"><div><span>合格标准</span><strong>${c.pass} / 100 分</strong></div><div><span>已用提示次数</span><strong id="usedHints">${a?.hints.length||0} / ${c.agent.limit} 次</strong></div><div><span>自动评测验证</span><strong>${state.domain==='vision'?(a?.checks||0)+' 次':(a?.runs.length||0)+' 次'}</strong></div><div><span>成绩状态</span><strong>${submitted?'交卷后查看':'交卷后生成'}</strong></div></div></section></aside></div>`}
function taskHelp(id,c){return {threshold:'选择合适阈值，分离零件与背景。',area:'调整最小轮廓面积，保留有效零件。',count:'参考样本包含 4 个独立目标。',pick:`完成 ${c.pieces} 个给定零件的抓取。`,sort:`圆形 → 料框 ${c.mapping?.circle}；方形 → 料框 ${c.mapping?.square}。`,safe:`接近高度 ≥ ${c.safeHeight} mm；速度 ≤ ${c.speedCap}%。`}[id]||''}
function visionWorkspace(){const a=attempt();return `<section class="panel"><div class="workspace-toolbar"><span>${icon('vision')} 图像处理实验台</span><small>固定合成样本 · 640 × 420</small></div><div class="vision-canvas-wrap"><div class="camera-card"><div class="camera-title"><span>原始图像</span><span>样本 CV-01</span></div><canvas id="original" aria-label="相机原始图像"></canvas></div><div class="camera-card"><div class="camera-title"><span>二值化与轮廓</span><span id="detectionLabel">${count()} 个目标</span></div><canvas id="processed" aria-label="二值化识别结果"></canvas></div></div><div class="vision-stats"><div>有效目标数<strong id="targetCount">${count()} <small>/ 4</small></strong></div><div>当前阈值<strong id="thresholdStat">${state.threshold}</strong></div><div>最小轮廓面积<strong id="areaStat">${state.minArea} <small>px²</small></strong></div></div><div class="targetheader">轮廓检测结果 <span>选中目标可查看位置</span></div><div class="table-scroll"><table><thead><tr><th>目标 ID</th><th>轮廓类型</th><th>中心坐标 / px</th><th>检测状态</th></tr></thead><tbody id="visionTargets">${visionRows()}</tbody></table></div><div class="exam-controls"><small>固定样本的参数演示，不连接真实相机</small><button class="btn soft" id="validateVision" ${!active()?'disabled':''}>验证当前结果</button></div></section>`}
function visionRows(){return objects.map((o,i)=>`<tr data-object="${i}" class="${state.selected===i?'selected':''}"><td><i class="dot ${o.shape==='square'?'blue':''}"></i>OBJ_${o.id}</td><td>${o.shape==='circle'?'圆形轮廓':'矩形轮廓'}</td><td>(${o.x}, ${o.y})</td><td style="color:${detected(o)?'#279778':'#b79562'}">${detected(o)?'已检出':'未检出'}</td></tr>`).join('')}
function visionParams(){const a=attempt(),c=currentConfig(),p=a?.params||{threshold:c.method==='otsu'?118:128,area:400};return `<section class="panel"><div class="panelhead">视觉参数 <small>考核操作区</small></div><div class="form"><div class="sectiontitle"><i class="square"></i>图像二值化</div><div class="field"><label>指定处理方法</label><select disabled><option>${c.method==='fixed'?'固定阈值二值化':'Otsu 自动阈值（样本演示）'}</option></select></div><div class="field"><label for="threshold">二值化阈值 <input id="thresholdNumber" aria-label="二值化阈值数值" type="number" min="0" max="255" value="${p.threshold}" ${!active()||!c.editable||c.method==='otsu'?'disabled':''}></label><input id="threshold" aria-label="二值化阈值" type="range" min="0" max="255" value="${p.threshold}" ${!active()||!c.editable||c.method==='otsu'?'disabled':''}><div class="range-label"><span>0</span><span>灰度阈值</span><span>255</span></div><div class="histogram" id="histogram"><div class="thresholdline" id="thresholdline" style="left:${p.threshold/255*100}%"></div></div></div><div class="field"><label for="minArea">最小轮廓面积 <span>px²</span></label><input id="minArea" aria-label="最小轮廓面积" type="number" min="0" max="6000" step="100" value="${p.area}" style="width:100%;height:33px" ${!active()?'disabled':''}></div><div class="switchrow"><span>显示目标轮廓</span><button class="switch ${state.contours?'on':''}" id="contourSwitch" role="switch" aria-label="显示目标轮廓" aria-checked="${state.contours}"></button></div><div class="hint">${c.method==='otsu'?'自动阈值固定为合成样本演示值 118。':!c.editable?'教师已锁定初始阈值，仅可调整轮廓面积。':'在左侧对比原图与处理结果，调整本案例的视觉参数。'}</div><button class="btn soft" id="resetVision" ${!active()?'disabled':''}>${icon('refresh')}恢复初始参数</button></div></section>`}
function robotWorkspace(){const a=attempt(),c=currentConfig();return `<section class="panel"><div class="workspace-toolbar"><span>${icon('robot')} 机械臂操作实验台</span><small>已知位姿 · 无视觉任务</small></div><div class="viewport"><canvas id="scene" aria-label="机械臂抓取与分类仿真场景"></canvas><div class="scene-label">六轴协作机械臂 · 独立操控案例</div><div class="scene-help">点击零件查看给定位姿</div><div class="viewportbadge">BASE &nbsp; | &nbsp; mm</div></div><div class="param-notice">任务规则：圆形 → 料框 ${c.mapping.circle}；方形 → 料框 ${c.mapping.square}。接近高度 ≥ ${c.safeHeight} mm，运动速度 ≤ ${c.speedCap}%。</div><div class="targetheader">案例给定的零件位姿 <span>无需识别或标定</span></div><div class="table-scroll"><table><thead><tr><th>零件</th><th>类别</th><th>X / mm</th><th>Y / mm</th><th>任务状态</th></tr></thead><tbody id="robotTargets">${robotRows()}</tbody></table></div><div class="exam-controls"><small id="robotRunStatus">${a?.lastRun?'已有完成的运行证据':'尚无完成的运行记录'}</small><button class="btn ${state.running?'':'primary'}" id="runRobot" ${!active()?'disabled':''}>${state.running?'■ 停止运行':icon('play')+'运行抓取分类'}</button></div></section>`}
function robotRows(){const a=attempt();return objects.map((o,i)=>{const item=a?.lastRun?.items.find(x=>x.index===i);return `<tr data-object="${i}" class="${state.selected===i?'selected':''}"><td><i class="dot ${o.shape==='square'?'blue':''}"></i>PART_${o.id}</td><td>${o.shape==='circle'?'圆形':'方形'}</td><td>${o.wx}</td><td>${o.wy}</td><td>${item?(item.picked?'已放置 → '+item.bin:'抓取失败'):'待操作'}</td></tr>`}).join('')}
function robotParams(){const a=attempt(),p=a?.params||{height:80,speed:30,mapping:{circle:'A',square:'B'}};return `<section class="panel"><div class="panelhead">抓取与分类设置 <small>考核操作区</small></div><div class="form"><div class="sectiontitle"><i class="square"></i>机械臂运动参数</div><div class="field"><label for="height">接近高度 <span><b id="heightValue">${p.height}</b> mm</span></label><input type="range" id="height" min="20" max="150" value="${p.height}" ${!active()||state.running?'disabled':''}></div><div class="field"><label for="speed">运动速度</label><select id="speed" ${!active()||state.running?'disabled':''}>${[30,60,100].map(v=>`<option value="${v}" ${p.speed===v?'selected':''}>${v}%</option>`).join('')}</select></div><div class="field"><label>分类放置策略</label><div class="task-mapping"><label>圆形零件<select data-student-bin="circle" aria-label="圆形零件目标料框" ${!active()||state.running?'disabled':''}>${binOptions(p.mapping.circle)}</select></label><label>方形零件<select data-student-bin="square" aria-label="方形零件目标料框" ${!active()||state.running?'disabled':''}>${binOptions(p.mapping.square)}</select></label></div></div><div class="sectiontitle" style="margin-top:22px"><i class="square"></i>末端点动</div><div class="robot-readout" id="readout">${readout()}</div><div class="jog"><button data-jog="-1" ${!active()||state.running?'disabled':''}>X − 5 mm</button><button data-jog="1" ${!active()||state.running?'disabled':''}>X + 5 mm</button><button id="gripBtn" ${!active()||state.running?'disabled':''}>${p.grip?'打开夹爪':'闭合夹爪'}</button><button id="homeBtn" ${!active()||state.running?'disabled':''}>返回初始位</button></div><div class="hint">参数修改后需重新运行，交卷采用最近一次完成运行的证据。点动与夹爪操作作为练习记录，不单独计分。</div></div></section>`}
function readout(){const o=objects[state.selected]||allObjects[0];return ['X','Y','Z'].map((s,i)=>`<div>${s} / mm<b>${[o.wx+(attempt()?.params.offset||0),o.wy,42][i].toFixed(1)}</b></div>`).join('')}
function studentAgent(){const a=attempt(),c=currentConfig(),p=c.agent,allowed=permissionInfo.filter(([id])=>p[id]).length;return `<section class="panel agent"><div class="panelhead agenthead"><span class="agenttitle"><span class="agentmark">${icon('spark')}</span>Agent 考核助教</span><small>按教师权限</small></div><div class="agentbody"><p class="agent-response" id="agentResponse">${!allowed||!p.limit?'本次考核已关闭 Agent 帮助。请独立完成任务。':`本次允许 ${allowed} 类帮助，最多 ${p.limit} 次。禁用类型不会提供答案或参数。`}</p><div class="agentchips">${permissionInfo.map(([id,name])=>`<button data-help="${id}" ${!active()||!p[id]||a.hints.length>=p.limit?'disabled':''}>${name}${!p[id]?' · 禁用':''}</button>`).join('')}</div><form class="agentinput" id="studentAgentForm"><input id="agentQuestion" aria-label="术语或操作说明问题" placeholder="询问术语或界面操作…" maxlength="300" ${!active()||!p.concept||a.hints.length>=p.limit?'disabled':''}><button aria-label="发送概念问题" ${!active()||!p.concept||a.hints.length>=p.limit?'disabled':''}>↑</button></form><div class="agent-counter" id="agentCounter">已用 ${a?.hints.length||0} / ${p.limit} 次 · 使用情况随卷提交</div></div></section>`}
function studentLogs(){const a=attempt();return `<section class="panel runtime"><div class="runtimehead"><button class="active">${state.domain==='vision'?'参数验证记录':'运行记录'}</button><span id="logState">${active()?'● 考核进行中':a?'● 已交卷':'● 待开始'}</span></div><div class="logs" id="logs">${(a?.logs||[]).length?a.logs.slice(-20).map(x=>`<div><span>${esc(x.time)}</span> &nbsp;${esc(x.text)}</div>`).join(''):(active()?'尚无操作记录。可调整参数并验证当前任务。':'尚无操作记录。开始考核后，可进行参数调试与任务验证。')}</div></section>`}
function addLog(text){const a=attempt();if(!a)return;a.logs.push({time:new Date().toLocaleTimeString('zh-CN',{hour12:false}),text});if(a.logs.length>100)a.logs.shift();save();if($('#logs')){$('#logs').innerHTML=a.logs.slice(-20).map(x=>`<div>${esc(x.time)} &nbsp;${esc(x.text)}</div>`).join('');$('#logs').scrollTop=99999}}
function startExam(){if(state.running)cancelRun();db.attempts[attemptKey()]=newAttempt(state.domain);state.selected=0;state.sorted=[];save();render();toast('考核已开始，当前发布版本与权限已锁定')}
function updateVision(){syncDrawing();$('#targetCount').innerHTML=count()+' <small>/ 4</small>';$('#thresholdStat').textContent=state.threshold;$('#areaStat').innerHTML=state.minArea+' <small>px²</small>';$('#detectionLabel').textContent=count()+' 个目标';$('#visionTargets').innerHTML=visionRows();$('#thresholdline').style.left=state.threshold/255*100+'%';drawCameras();bindObjectSelection()}
function updateRobot(){syncDrawing();$('#robotTargets').innerHTML=robotRows();$('#readout').innerHTML=readout();drawScene();bindObjectSelection()}
function bindObjectSelection(){$$('[data-object]').forEach(el=>el.onclick=()=>{state.selected=+el.dataset.object;state.domain==='vision'?updateVision():updateRobot()});if($('#scene'))$('#scene').onclick=e=>{const r=e.currentTarget.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*800,y=(e.clientY-r.top)/r.height*430;let best=0,dist=Infinity;objects.forEach((o,i)=>{const d=(x-400-(o.wx-o.wy)*1.06)**2+(y-245-(o.wx+o.wy)*.44)**2;if(d<dist){dist=d;best=i}});if(dist<10000){state.selected=best;updateRobot()}};['original','processed'].forEach(id=>{if($('#'+id))$('#'+id).onclick=e=>{const r=e.currentTarget.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*640,y=(e.clientY-r.top)/r.height*420;objects.forEach((o,i)=>{if(Math.abs(x-o.x)<o.r+20&&Math.abs(y-o.y)<o.r+20)state.selected=i});updateVision()}})}
function markParamChange(){save();if(state.domain==='robot'&&$('#robotRunStatus'))$('#robotRunStatus').textContent='参数已修改，请重新运行以更新交卷证据'}
function bindStudent(){if($('#startExam'))$('#startExam').onclick=startExam;if($('#submitTop'))$('#submitTop').onclick=confirmSubmit;if($('#viewSubmission'))$('#viewSubmission').onclick=()=>showRecord(db.records.find(r=>r.id===attempt().recordId));if($('#newExam'))$('#newExam').onclick=()=>openModal('开始新的考核练习','上一份交卷记录将保留，新练习使用最新发布配置。',`<p class="modal-body-text">开始后将重新计时，当前案例采用已发布 v${pub().version}。另一个教学案例的考核不受影响。</p>`,`<button class="btn primary" id="confirmNew">开始新练习</button>`,()=>{$('#confirmNew').onclick=()=>{closeModal();startExam()}});$('#bottomAction').onclick=()=>active()?confirmSubmit():attempt()?.status==='submitted'?showRecord(db.records.find(r=>r.id===attempt().recordId)):startExam();$('#explanation').oninput=e=>{if(!active())return;attempt().explanation=e.target.value;$('#wordCount').textContent=e.target.value.length+' / 2000';save()};if(state.domain==='vision'){['threshold','thresholdNumber'].forEach(id=>$('#'+id).oninput=e=>{if(!active())return;attempt().params.threshold=Math.max(0,Math.min(255,+e.target.value||0));$('#threshold').value=$('#thresholdNumber').value=attempt().params.threshold;save();updateVision()});$('#minArea').oninput=e=>{if(!active())return;attempt().params.area=Math.max(0,Math.min(6000,+e.target.value||0));save();updateVision()};$('#contourSwitch').onclick=()=>{state.contours=!state.contours;$('#contourSwitch').classList.toggle('on',state.contours);$('#contourSwitch').setAttribute('aria-checked',state.contours);drawCameras()};$('#resetVision').onclick=()=>{attempt().params={threshold:currentConfig().method==='otsu'?118:128,area:400};save();render();toast('已恢复初始视觉参数')};$('#validateVision').onclick=()=>{attempt().checks++;attempt().lastCheck={threshold:state.threshold,area:state.minArea,count:count(),at:Date.now()};addLog(`验证 ${attempt().checks}：阈值 ${state.threshold}，最小面积 ${state.minArea} px²，检出 ${count()} / 4 个目标`);render();toast('当前检测结果已记录，评分在交卷后生成')}}else{$('#height').oninput=e=>{attempt().params.height=+e.target.value;$('#heightValue').textContent=e.target.value;markParamChange()};$('#speed').onchange=e=>{attempt().params.speed=+e.target.value;markParamChange()};$$('[data-student-bin]').forEach(el=>el.onchange=()=>{attempt().params.mapping[el.dataset.studentBin]=el.value;markParamChange()});$$('[data-jog]').forEach(el=>el.onclick=()=>{attempt().params.offset+=+el.dataset.jog*5;updateRobot();addLog(`末端 X 方向点动 ${+el.dataset.jog*5} mm`)});$('#gripBtn').onclick=()=>{attempt().params.grip=!attempt().params.grip;$('#gripBtn').textContent=attempt().params.grip?'打开夹爪':'闭合夹爪';updateRobot();addLog(attempt().params.grip?'夹爪闭合':'夹爪打开')};$('#homeBtn').onclick=()=>{attempt().params.offset=0;attempt().params.grip=false;save();render();toast('机械臂返回初始位')};$('#runRobot').onclick=()=>state.running?cancelRun():runRobot()};$$('[data-help]').forEach(el=>el.onclick=()=>requestHelp(el.dataset.help));$('#studentAgentForm').onsubmit=e=>{e.preventDefault();const q=$('#agentQuestion').value.trim();if(q)requestHelp('concept',q)};bindObjectSelection()}
function cancelRun(){cancelAnimationFrame(animFrame);state.running=false;state.phase=0;runQueue=[];addLog('本次运行已停止；未完成的运行不计入评分证据');render()}
function runRobot(){if(!active())return;const a=attempt();state.running=true;state.pickAllowed=a.params.height>=a.config.safeHeight;state.sorted=[];state.phase=0;runQueue=objects.map((_,i)=>i);state.activeObject=0;runSnapshot={...clone(a.params),items:[],started:Date.now(),domain:state.domain};a.lastRun=null;addLog(`开始运行：接近高度 ${runSnapshot.height} mm，速度 ${runSnapshot.speed}%，圆形→${runSnapshot.mapping.circle}，方形→${runSnapshot.mapping.square}`);render();runStart=performance.now();animFrame=requestAnimationFrame(animateRobot)}
function animateRobot(t){if(!state.running||!active())return;state.phase=Math.min(1,(t-runStart)/(1700*(60/runSnapshot.speed)));drawScene();if(state.phase>=1){const i=state.activeObject,o=objects[i],c=currentConfig(),picked=runSnapshot.height>=c.safeHeight,bin=runSnapshot.mapping[o.shape];runSnapshot.items.push({index:i,id:o.id,shape:o.shape,picked,bin,correct:picked&&bin===c.mapping[o.shape]});if(picked)state.sorted.push(i);addLog(`PART_${o.id}：${picked?'抓取完成 → 料框 '+bin:'接近高度不足，演示抓取失败'}`);runQueue.shift();if(!runQueue.length){state.running=false;state.phase=0;attempt().lastRun={...clone(runSnapshot),finished:Date.now()};attempt().runs.push(clone(attempt().lastRun));save();addLog('运行结束：已保存参数快照与分类证据');render();toast('本次抓取分类运行完成，证据已保存');return}state.activeObject=runQueue[0];state.selected=state.activeObject;state.phase=0;runStart=t;if($('#robotTargets')){$('#robotTargets').innerHTML=robotRows();bindObjectSelection()}}animFrame=requestAnimationFrame(animateRobot)}
function requestHelp(type,question=''){if(!active())return;const a=attempt(),p=a.config.agent;const answer=$('#agentResponse');if(!p[type]||a.hints.length>=p.limit){answer.textContent=!p[type]?'教师已禁用此类帮助。':'本次考核的提示次数已用完。';return}let text='';if(type==='concept'&&question){const q=question.replace(/\s/g,'');const forbidden=/\d|推荐|多少|答案|建议|怎么调|如何调|帮我|代码|诊断|检查|对不对|正确|料框|参数值|策略/;const safe=state.domain==='vision'?/^(什么是(二值化|阈值|轮廓|灰度)|解释(二值化|阈值|轮廓|灰度)|二值化(是什么|原理)|阈值(是什么|含义)|轮廓(是什么|含义)|灰度(是什么|含义)|怎么(提交|交卷)|如何(提交|交卷))[？?。！!]*$/:/^(什么是(接近高度|末端|点动|夹爪)|解释(接近高度|末端|点动|夹爪)|接近高度(是什么|含义)|点动(是什么|含义)|怎么(提交|交卷)|如何(提交|交卷))[？?。！!]*$/;if(forbidden.test(q)||!safe.test(q)){answer.textContent='自由提问仅支持术语与操作说明，例如“什么是阈值”或“什么是接近高度”。具体诊断、参数或程序帮助请使用对应权限入口。';return}text=/提交|交卷/.test(q)?'完成任务后点击「提交考核」，检查证据摘要并确认交卷。交卷后操作将锁定。':state.domain==='vision'?'二值化将灰度像素划分为前景与背景；阈值是划分界限。轮廓描述前景目标的边界。这是概念说明，不包含当前参数建议。':'接近高度是机械臂接近零件前保留的高度；点动用于小步移动末端。请依据任务要求独立设置参数。'}else if(type==='concept')text=state.domain==='vision'?'二值化把灰度图划分为前景和背景；轮廓面积筛选用于去除过小区域。请根据图像现象独立判断参数。':'接近高度用于为机械臂接近零件预留空间；分类放置策略将已知零件类别映射到料框。';else if(type==='diagnose')text=state.domain==='vision'?`当前检出 ${count()} / 4 个目标。${count()<4?'可检查前景是否完整、是否被面积过滤。':'当前样本的目标均已检出，请检查参数选择依据是否写入说明。'}`:a.lastRun?`最近完成运行：抓取 ${a.lastRun.items.filter(x=>x.picked).length} / ${a.config.pieces} 个；正确分类 ${a.lastRun.items.filter(x=>x.correct).length} 个。请对照任务要求检查。`:'尚无完成的运行记录。先运行一次抓取分类，再诊断执行结果。';else if(type==='recommend')text=state.domain==='vision'?`本案例可从阈值 ${a.config.tmin}–${a.config.tmax}、最小面积 ${a.config.amin}–${a.config.amax} px² 的区间尝试，并结合图像验证。`:`本案例要求接近高度至少 ${a.config.safeHeight} mm、速度不超过 ${a.config.speedCap}%；圆形放入 ${a.config.mapping.circle}，方形放入 ${a.config.mapping.square}。`;else if(type==='code')text=state.domain==='vision'?'示例伪代码：gray = grayscale(image) → mask = gray > threshold → contours(mask) → filter(area >= minArea)。':'示例伪代码：for part in known_parts → approach(part.pose) → grip() → lift() → place(bin_for(part.type))。';a.hints.push({type,question:question.slice(0,300),response:text,at:Date.now()});save();answer.textContent=text;$('#agentCounter').textContent=`已用 ${a.hints.length} / ${p.limit} 次 · 使用情况随卷提交`;$('#usedHints').textContent=`${a.hints.length} / ${p.limit} 次`;if($('#agentQuestion'))$('#agentQuestion').value='';$$('[data-help]').forEach(b=>b.disabled=!p[b.dataset.help]||a.hints.length>=p.limit);if(a.hints.length>=p.limit){$('#agentQuestion').disabled=true;$('#studentAgentForm button').disabled=true}}
function visionEvidence(a){const p=a.params;const hits=allObjects.map(o=>({id:o.id,detected:p.threshold>=48&&p.threshold<o.v&&(o.shape==='circle'?Math.PI*o.r*o.r:4*o.r*o.r)>=p.area,x:o.x,y:o.y}));return {threshold:p.threshold,area:p.area,method:a.config.method,targets:hits,count:hits.filter(o=>o.detected).length}}
function gradeAttempt(k,a){const c=a.config,e=k==='vision'?visionEvidence(a):a.lastRun?clone(a.lastRun):null;const scores=c.rubric.filter(r=>r.on).map(r=>{let ratio=0;if(r.id==='analysis')return {...clone(r),earned:null,manual:true};if(k==='vision'){if(r.id==='threshold')ratio=e.threshold>=c.tmin&&e.threshold<=c.tmax?1:0;if(r.id==='area')ratio=e.area>=c.amin&&e.area<=c.amax?1:0;if(r.id==='count')ratio=e.count/4}else if(e){if(r.id==='pick')ratio=e.items.filter(x=>x.picked).length/c.pieces;if(r.id==='sort')ratio=e.items.filter(x=>x.correct).length/c.pieces;if(r.id==='safe')ratio=e.height>=c.safeHeight&&e.speed<=c.speedCap?1:0}return {...clone(r),earned:Math.round(r.weight*ratio*10)/10,manual:false}});return {evidence:e,scores,automatic:Math.round(scores.filter(s=>!s.manual).reduce((n,s)=>n+s.earned,0)*10)/10,pending:scores.some(s=>s.manual),manualScore:null,feedback:''}}
function confirmSubmit(){if(!active())return;if(state.running)return toast('请先停止或完成本次运行，再提交考核');const a=attempt(),e=state.domain==='vision'?visionEvidence(a):a.lastRun;const unsynced=state.domain==='robot'&&e&&(e.height!==a.params.height||e.speed!==a.params.speed||JSON.stringify(e.mapping)!==JSON.stringify(a.params.mapping));openModal('确认提交考核',`${state.domain==='vision'?'机器视觉':'机械臂操控'} · 配置 v${a.config.version}`,`<div class="summary-list"><div><span>考核案例</span><strong>${esc(a.config.name)}</strong></div><div><span>本次证据</span><strong>${state.domain==='vision'?`阈值 ${e.threshold} · 面积 ${e.area} · 检出 ${e.count} / 4`:e?`最近完成运行 · ${e.items.length} 个零件`:'尚无完成运行证据，自动项将计 0 分'}</strong></div><div><span>分析说明</span><strong>${a.explanation.length} 字</strong></div><div><span>Agent 使用</span><strong>${a.hints.length} 次</strong></div></div>${unsynced?'<div class="validation">当前参数与最近完成运行不同。本次交卷采用最近完成运行的参数与结果；如需更新，请返回重新运行。</div>':''}${!a.explanation.trim()&&a.config.rubric.find(r=>r.id==='analysis').on?'<div class="subtle-note">尚未填写分析说明。可以返回补充，或交卷后由教师据实评阅。</div>':''}<p class="modal-body-text">确认后将冻结本次考核配置、参数证据与提示记录，无法继续修改。另一类教学任务不受影响。</p>`,`<button class="btn" id="returnExam">返回检查</button><button class="btn primary" id="confirmSubmit">确认交卷</button>`,()=>{$('#returnExam').onclick=closeModal;$('#confirmSubmit').onclick=()=>{closeModal();const rec=submitAttempt(state.domain,a,false);render();showRecord(rec)}})}
function submitAttempt(k,a,auto){if(a.status!=='active')return db.records.find(r=>r.id===a.recordId);const graded=gradeAttempt(k,a),record={id:a.id,domain:k,caseId:a.caseId,courseId:a.courseId,mode:a.mode||'exam',config:clone(a.config),submitted:Date.now(),started:a.started,autoSubmitted:auto,explanation:a.explanation,hints:clone(a.hints),logs:clone(a.logs),checks:a.checks,runs:clone(a.runs),...graded};a.status='submitted';a.recordId=record.id;db.records.unshift(record);save();return record}
function recordsPage(){const records=db.records.filter(r=>r.domain===state.domain&&(state.recordMode==='all'||(r.mode||'exam')===state.recordMode)&&(state.role==='teacher'||(r.studentId||'self')===(state.studentId||'self')));return `<div class="titleline"><h1>${state.role==='teacher'?'考核评阅':'我的考核记录'}</h1><span class="tag">${state.role==='teacher'?'教师端':'学生端'}</span><div class="titleactions"><button class="btn" id="backToConfig">${state.role==='teacher'?'返回案例配置':'返回考核台'}</button></div></div><p class="subtitle">按教学类型独立查看成绩与证据。${state.role==='teacher'?'完成说明题评阅后，生成最终成绩与合格结果。':'自动评测结果和教师评阅共同构成最终成绩。'}</p>${domains()}${records.length?`<div class="report-grid">${records.map(r=>`<button class="record-card" data-record="${r.id}"><div style="display:flex;justify-content:space-between;gap:10px"><span class="type-label ${r.domain==='robot'?'robot':''}">${r.domain==='vision'?'机器视觉':'机械臂操控'}</span><span class="tag ${r.pending?'orange':'green'}">${r.pending?'待教师评阅':finalScore(r)>=r.config.pass?'已合格':'未达标'}</span></div><h3 style="margin-top:18px">${esc(r.config.name)}</h3><p>${esc(r.id)} · 配置 v${r.config.version}</p><p>${new Date(r.submitted).toLocaleString('zh-CN',{hour12:false})}${r.autoSubmitted?' · 到时自动交卷':''}</p><div class="record-score">${r.pending?(r.config.engine==='plan'?'—':r.automatic):finalScore(r)} <small>${r.pending?(r.config.engine==='plan'?'方案待教师评阅':'自动评测分 · 人工项待评阅'):'/ 100 分'}</small></div><div class="thumbline"><i style="width:${r.pending?(r.config.engine==='plan'?'—':r.automatic):finalScore(r)}%"></i></div></button>`).join('')}</div>`:`<section class="panel empty-state">${icon('chart')}<h3>还没有${state.domain==='vision'?'视觉':'操控'}考核交卷记录</h3><p>学生完成本类型考核后，记录与评阅入口会出现在这里。</p><button class="btn soft" id="goStudent">进入学生考核</button></section>`}`}
function finalScore(r){return Math.round((r.automatic+(r.manualScore||0))*10)/10}
function evidenceHtml(r){if(r.domain==='vision'){const e=r.evidence;return `<div class="summary-list"><div><span>二值化阈值</span><strong>${e.threshold}</strong></div><div><span>最小轮廓面积</span><strong>${e.area} px²</strong></div><div><span>有效检出</span><strong>${e.count} / 4</strong></div></div>`}const e=r.evidence;return e?`<div class="summary-list"><div><span>接近高度 / 速度</span><strong>${e.height} mm / ${e.speed}%</strong></div><div><span>圆形 / 方形目标</span><strong>料框 ${e.mapping.circle} / 料框 ${e.mapping.square}</strong></div><div><span>成功抓取 / 正确分类</span><strong>${e.items.filter(x=>x.picked).length} / ${e.items.filter(x=>x.correct).length} 个</strong></div></div>`:'<div class="subtle-note">本次交卷没有完成的抓取分类运行证据。</div>'}
function showRecord(r){if(!r)return toast('未找到本次交卷记录');const manual=r.scores.find(x=>x.manual),teacher=state.role==='teacher';openModal(teacher?'考核评阅与证据':'考核交卷结果',`${r.domain==='vision'?'机器视觉':'机械臂操控'} · 配置 v${r.config.version} · ${r.id}`,`<div class="review-outcome"><div class="score">${r.pending?(r.config.engine==='plan'?'—':r.automatic):finalScore(r)}<small> 分</small></div><div><h3 style="font-size:15px;margin:0">${r.pending?(r.config.engine==='plan'?'方案已提交，待教师评阅':'自动评测完成，待教师评阅'):finalScore(r)>=r.config.pass?'本次考核已合格':'本次考核未达合格标准'}</h3><p>${r.pending?`人工评阅项满分 ${manual?.weight||0} 分，尚未计入总分。`:`合格标准 ${r.config.pass} 分 · 最终成绩 ${finalScore(r)} / 100。`}</p>${r.autoSubmitted?'<p>考核时间结束，系统已自动交卷。</p>':''}</div></div><table class="rubric"><thead><tr><th>评分项目</th><th>方式</th><th>得分 / 满分</th></tr></thead><tbody>${r.scores.map(s=>`<tr><td>${s.name}</td><td>${s.manual?'教师评阅':'自动评测'}</td><td>${s.manual?(r.pending?'待评阅':r.manualScore):s.earned} / ${s.weight}</td></tr>`).join('')}</tbody></table><div class="form-divider"></div><div class="fieldtitle">冻结的交卷证据 <span>独立案例，无跨课程串联</span></div>${evidenceHtml(r)}<div class="fieldtitle" style="margin-top:18px">${r.domain==='vision'?'实验分析说明':'操作策略说明'}</div><p class="modal-body-text" style="white-space:pre-wrap;background:#f7f9fc;padding:13px;border-radius:6px">${esc(r.explanation||'学生未填写说明。')}</p><details style="margin:18px 0;color:#7188a9;font-size:12px"><summary>Agent 提示使用记录 · ${r.hints.length} 次</summary><div class="modal-body-text">${r.hints.length?r.hints.map(h=>`<p>${new Date(h.at).toLocaleTimeString('zh-CN')} · ${permissionInfo.find(x=>x[0]===h.type)?.[1]}<br>${esc(h.response)}</p>`).join(''):'本次考核未使用 Agent 帮助。'}</div></details>${teacher&&manual?`<div class="form-divider"></div><div class="fieldtitle">教师评阅 <span>人工项满分 ${manual.weight} 分</span></div><label class="modal-body-text">人工评分 <input id="manualScore" class="rule-input review-score" type="number" min="0" max="${manual.weight}" value="${r.manualScore??''}" aria-label="人工评分"> / ${manual.weight} 分</label><div style="margin-top:13px"><label class="modal-body-text" for="reviewFeedback">评阅反馈</label><textarea id="reviewFeedback" class="review-textarea" maxlength="1200" placeholder="填写分析依据或改进建议…">${esc(r.feedback)}</textarea></div><div id="reviewError" style="color:#b98348;font-size:11px;margin-top:9px"></div>`:r.feedback?`<div class="hint">教师反馈：${esc(r.feedback)}</div>`:''}<p class="small-label">原型演示成绩仅基于合成样本或预设运动证据，角色切换不代表真实身份认证。</p>`,`<button class="btn" id="exportRecord">导出报告</button>${teacher&&manual?'<button class="btn primary" id="saveReview">保存评阅结果</button>':'<button class="btn primary" id="finishRecord">返回工作台</button>'}`,()=>{$('#exportRecord').onclick=()=>downloadRecord(r);if($('#finishRecord'))$('#finishRecord').onclick=closeModal;if($('#saveReview'))$('#saveReview').onclick=()=>{const value=$('#manualScore').value,n=Number(value);if(value===''||!Number.isFinite(n)||n<0||n>manual.weight){$('#reviewError').textContent=`请填写 0–${manual.weight} 的有效分数。`;return}r.manualScore=Math.round(n*10)/10;r.pending=false;r.feedback=$('#reviewFeedback').value;r.reviewedAt=Date.now();save();render();showRecord(r);toast('评阅结果已保存，最终成绩已更新')}})}
function downloadRecord(r){const blob=new Blob([JSON.stringify({...r,prototype:true},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=r.id+'-考核报告.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('报告已导出')}
function bindRecords(){$$('[data-record]').forEach(b=>b.onclick=()=>showRecord(db.records.find(r=>r.id===b.dataset.record)));$('#backToConfig').onclick=()=>{state.page='config';render()};if($('#goStudent'))$('#goStudent').onclick=()=>{state.role='student';state.page='config';render()}}
let lastFocus=null;function openModal(title,sub,body,footer='',bind){lastFocus=document.activeElement;$('#modalRoot').innerHTML=`<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalhead"><div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div><button class="btn" id="closeModal" aria-label="关闭">×</button></div><div class="modalbody">${body}</div>${footer?`<div class="modalfoot">${footer}</div>`:''}</section></div>`;$('#closeModal').onclick=closeModal;$('.overlay').onclick=e=>{if(e.target===$('.overlay'))closeModal()};bind?.();$('#closeModal').focus()}
function closeModal(){$('#modalRoot').innerHTML='';if(lastFocus?.isConnected)lastFocus.focus()}
function navigate(fn){if(state.running){toast('请先停止或完成当前抓取运行，再切换界面');return}fn();state.selected=0;state.sorted=[];render()}
function bindGlobal(){$$('[data-role]').forEach(b=>b.onclick=()=>navigate(()=>{state.role=b.dataset.role;state.page='config'}));$$('[data-domain]').forEach(b=>b.onclick=()=>navigate(()=>{state.domain=b.dataset.domain}));$$('[data-page]').forEach(b=>b.onclick=()=>navigate(()=>{state.page=b.dataset.page}));$('#aboutBtn').onclick=()=>openModal('教学工作台原型','教师设计、学生考核与人工评阅',`<div class="modal-body-text"><p>机器视觉与机械臂操控是独立案例，分别配置、发布、计时和评分。</p><p>教师配置在发布后应用于新考核。学生交卷时冻结参数和使用记录，人工说明题由教师评阅。</p><p>当前内容保存在本机浏览器。角色切换用于界面评审，不提供真实身份、跨设备同步或正式考试防作弊能力。</p><p>视觉采用合成样本，机械臂采用预设运动，Agent 使用预设引导。</p></div>`)}
function drawHistogram(){if(!$('#histogram'))return;$('#histogram').insertAdjacentHTML('afterbegin',Array.from({length:52},(_,i)=>`<i style="height:${7+46*Math.exp(-(((i-12)/6)**2))+37*Math.exp(-(((i-36)/5)**2))}px"></i>`).join(''))}
function updateClock(){for(const [k,a] of Object.entries(db.attempts)){if(a.status!=='active'||a.mode==='practice')continue;const secs=remaining(a);if(secs<=0){if(state.running&&attemptKey()===k){cancelAnimationFrame(animFrame);state.running=false;state.phase=0}const rec=submitAttempt(a.domain,a,true);if(state.role==='student'&&attemptKey()===k){closeModal();render();showRecord(rec)}continue}if(state.role==='student'&&attemptKey()===k){if($('#examClock'))$('#examClock').textContent=timeFormat(secs);if($('#bannerClock'))$('#bannerClock').textContent=timeFormat(secs)}}}
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){const focusable=[...$('.modal').querySelectorAll('button,input,textarea,select,[tabindex]')].filter(x=>!x.disabled&&x.offsetParent!==null),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});window.addEventListener('resize',()=>requestAnimationFrame(()=>{drawCameras();drawScene()}));window.addEventListener('beforeunload',save);
